import{_ as i,C as t,o as r,c as s,ai as a,E as d}from"./chunks/framework.kPxgjqLK.js";const f=JSON.parse('{"title":"Das persönliche Agenten-System","description":"","frontmatter":{"title":"Das persönliche Agenten-System"},"headers":[],"relativePath":"kapitel/04-persoenliches-agenten-system.md","filePath":"kapitel/04-persoenliches-agenten-system.md"}'),l={name:"kapitel/04-persoenliches-agenten-system.md"};function o(u,e,h,g,m,c){const n=t("FeedbackForm");return r(),s("div",null,[e[0]||(e[0]=a('<h2 id="kapitel-4-das-personliche-agenten-system" tabindex="-1">Kapitel 4: Das persönliche Agenten-System <a class="header-anchor" href="#kapitel-4-das-personliche-agenten-system" aria-label="Permalink to &quot;Kapitel 4: Das persönliche Agenten-System&quot;">​</a></h2><h2 id="rollen-regeln-speicher-und-routinen" tabindex="-1">Rollen, Regeln, Speicher und Routinen <a class="header-anchor" href="#rollen-regeln-speicher-und-routinen" aria-label="Permalink to &quot;Rollen, Regeln, Speicher und Routinen&quot;">​</a></h2><p>Sie öffnen Claude Code an einem Montagmorgen. Der Agent kennt Ihre Arbeitsweise, weiß welche Projekte gerade laufen, erinnert sich an Ihre Stilpräferenzen, kennt die Kunden, für die Sie arbeiten, und weiß, was letzte Woche noch offen geblieben ist. Sie müssen nichts erklären. Sie können sofort mit der Aufgabe beginnen.</p><p>Das ist kein Zufall. Das ist das Ergebnis einer bewussten Entscheidung, wie Sie Ihren Agenten einrichtest. Ein Agent, dem Sie nie sagst, wer Sie sind und wie Sie arbeiten, ist ein Agent, dem Sie immer wieder alles von vorne erklären musst. Ein Agent, der in einem sorgfältig aufgebauten Kontext arbeitet, wird schnell zu einem echten Begleiter der eigenen Arbeit.</p><p>Dieses Kapitel zeigt Ihnen, wie Sie aus einzelnen Prompts und Werkzeugkonfigurationen ein zusammenhängendes, persönliches Agenten-System aufbaust. Das kostet am Anfang etwas Zeit. Aber es ist die Investition, die jede spätere Arbeit effizienter macht.</p><h2 id="was-ein-personliches-agenten-system-ist" tabindex="-1">Was ein persönliches Agenten-System ist <a class="header-anchor" href="#was-ein-personliches-agenten-system-ist" aria-label="Permalink to &quot;Was ein persönliches Agenten-System ist&quot;">​</a></h2><p>Ein persönliches Agenten-System ist kein einzelnes Werkzeug und kein einzelner Prompt. Es ist die Gesamtheit aus Rollen, die Sie Ihren Agenten gibst, Regeln, nach denen sie arbeiten, Speicher, in dem sie relevante Informationen über Sitzungen hinaus festhalten, und Routinen, die regelmäßig wiederkehrende Aufgaben automatisch anstoßen.</p><p>Stellen Sie sich das wie ein kleines Büro vor. Es gibt bestimmte Aufgabenbereiche, für die Sie Zuständigkeiten vergibst. Es gibt Arbeitsregeln, die für alle gelten. Es gibt Ablagesysteme, in denen Wissen gesammelt wird. Und es gibt Abläufe, die jede Woche nach dem gleichen Schema durchgeführt werden.</p><p>Das Ziel ist nicht, möglichst viel zu automatisieren. Das Ziel ist, ein System aufzubauen, das Ihnen jede Woche spürbar Zeit spart, das zuverlässig und nachvollziehbar arbeitet und das sich mit Ihrer Arbeit weiterentwickelt.</p><h2 id="rollen-agenten-mit-klaren-zustandigkeiten" tabindex="-1">Rollen: Agenten mit klaren Zuständigkeiten <a class="header-anchor" href="#rollen-agenten-mit-klaren-zustandigkeiten" aria-label="Permalink to &quot;Rollen: Agenten mit klaren Zuständigkeiten&quot;">​</a></h2><p>Der erste Schritt beim Aufbau eines persönlichen Agenten-Systems ist die Definition von Rollen. Eine Rolle beschreibt, für welche Art von Aufgaben ein Agent zuständig ist, welchen Kontext er dafür braucht, welche Werkzeuge er nutzen darf und wie er Ergebnisse präsentieren soll.</p><p>Warum Rollen? Weil ein Agent, dem Sie sagen &quot;Sie sind mein Recherche-Assistent, der belastbare Zusammenfassungen mit Quellenangaben liefert und Unsicherheiten markiert&quot;, konsequenter und vorhersehbarer arbeitet als ein Agent, dem Sie jedes Mal eine neue Aufgabe ohne Kontext gibst.</p><p>Für Selbständige sind einige Rollen besonders nützlich.</p><p>Der Recherche-Assistent ist zuständig für Marktanalysen, Wettbewerbsrecherchen, Quellenprüfungen und Themenaufbereitungen. Er liefert immer ein Kurzfazit, belegbare Fakten, Quellenangaben und eine explizite Liste von Unsicherheiten.</p><p>Der Schreib-Assistent ist zuständig für Textentywrfe, Überarbeitungen, Formatierungen und Stilanpassungen. Er kennt Ihren Schreibstil, Ihre bevorzugte Satzlänge, Ihre Formulierungsregeln und Ihre Zielgruppen. Er macht Vorschläge, entscheidet aber nie selbst über Veröffentlichungen.</p><p>Der Projektassistent ist zuständig für das Begleiten laufender Projekte: Aufgabenlisten prüfen, Stände zusammenfassen, nächste Schritte vorschlagen, Blockaden markieren. Er kennt die Projekte, ihre Zeitrahmen und ihre Prioritäten.</p><p>Der Kommunikationsassistent ist zuständig für E-Mail-Entwürfe, Follow-up-Nachrichten und Angebotsvorbereitung. Er formuliert, liefert aber immer Entwürfe zur menschlichen Freigabe.</p><p>Jede dieser Rollen kann in einem einzigen Agenten oder in mehreren Agenten abgebildet werden. Die Entscheidung hängt davon ab, welche Werkzeuge für welche Rollen nötig sind und wie klar die Aufgabenbereiche voneinander getrennt bleiben sollen.</p><h2 id="kontextdateien-das-gedachtnis-das-sie-schreiben" tabindex="-1">Kontextdateien: Das Gedächtnis, das Sie schreiben <a class="header-anchor" href="#kontextdateien-das-gedachtnis-das-sie-schreiben" aria-label="Permalink to &quot;Kontextdateien: Das Gedächtnis, das Sie schreiben&quot;">​</a></h2><p>Jede Claude-Code-Sitzung beginnt ohne Erinnerung an vorherige Gespräche. Was sich über Sitzungen hinaus erhalten kann, kommt aus zwei Quellen: Dateien, die Sie selbst pflegst, und Auto-Memory, das Claude Code beim Arbeiten automatisch anlegt.</p><p>Das wichtigste Element ist die CLAUDE.md-Datei. Die offizielle Dokumentation beschreibt sie so: Behandle CLAUDE.md als den Ort, an dem Sie aufschreibst, was Sie sonst erneut erklären würdest. Das trifft es präzise. Alles, was Sie einem neuen Mitarbeiter am ersten Tag mitteilen würdest, gehört in diese Datei.</p><p>Konkret enthält eine gut gepflegte CLAUDE.md für Selbständige typischerweise folgendes: eine kurze Beschreibung der eigenen Tätigkeit und Zielgruppe, die wichtigsten laufenden Projekte mit Status, Stilregeln für Texte und Kommunikation, bevorzugte Ausgabeformate für verschiedene Aufgabentypen, wiederkehrende Aufgaben und ihre Erwartungsformate, sowie Dinge, die der Agent niemals tun soll, also explizite Grenzen.</p><p>Eine CLAUDE.md muss nicht lang sein. Eine gut strukturierte Datei mit einem bis zwei Seiten Text leistet mehr als ein zehn Seiten langes Dokument, das niemand aktuell hält. Die Dokumentation empfiehlt, spezifisch und prägnant zu schreiben, weil ein Agent spezifischen Anweisungen konsequenter folgt als allgemeinen.</p><p>CLAUDE.md-Dateien können auf mehreren Ebenen vorhanden sein. Eine globale Datei enthält allgemeine Informationen über Sie und Ihre Arbeitsweise, die für alle Projekte gelten. Projektspezifische Dateien enthalten Informationen, die nur für ein bestimmtes Projekt relevant sind. Claude Code liest beide Ebenen und kombiniert sie automatisch.</p><p>Für Codex gibt es die entsprechende AGENTS.md-Datei, die exakt dieselbe Funktion erfüllt. Sie enthält Arbeitsregeln, Berechtigungen, Hooks und projektspezifische Anweisungen. Das AGENTS.md-Format ist in über 60.000 Open-Source-Projekten verbreitet und hat sich als offener Standard etabliert. In größeren Projekten mit vielen Unterordnern können verschachtelte AGENTS.md-Dateien in jedem Unterordner liegen, wobei der Agent immer die nächste vorhandene Datei im Verzeichnisbaum liest.</p><h2 id="auto-memory-das-gedachtnis-das-von-selbst-wachst" tabindex="-1">Auto-Memory: Das Gedächtnis, das von selbst wächst <a class="header-anchor" href="#auto-memory-das-gedachtnis-das-von-selbst-wachst" aria-label="Permalink to &quot;Auto-Memory: Das Gedächtnis, das von selbst wächst&quot;">​</a></h2><p>Neben den Dateien, die Sie selbst schreibst, hat Claude Code ein Auto-Memory-System. Wenn Sie während einer Sitzung sagst &quot;Denke daran, immer mit kurzen Sätzen zu schreiben&quot; oder wenn Sie eine Korrektur am Stil des Agenten vornimmst, kann Claude Code diese Information selbständig in eine Memory-Datei schreiben und beim nächsten Start wieder abrufen.</p><p>Claude Code speichert nicht nach jeder Sitzung automatisch alles. Es entscheidet selbst, welche Informationen für zukünftige Sitzungen nützlich sein könnten: Build-Befehle, Debugging-Erkenntnisse, Architekturentscheidungen, Stilvorlieben und Arbeitsgewohnheiten. Die ersten 200 Zeilen oder 25 Kilobyte der Memory-Datei werden bei Sitzungsstart geladen. Darüber hinausgehende Informationen werden in separate Themendateien ausgelagert.</p><p>Das ist ein mächtiges System, das aber regelmäßiger Pflege bedarf. Über Zeit kann Auto-Memory mit veralteten oder widersprüchlichen Einträgen volllaufen. Prüfe die Memory-Dateien Ihres Agenten daher in regelmäßigen Abständen, entferne irrelevante Einträge und aktualisiere veraltete Informationen. Die Memory-Dateien sind einfache Textdateien, die Sie jederzeit bearbeiten oder löschen können.</p><h2 id="hermes-memory-der-langlebige-personliche-kontext" tabindex="-1">Hermes-Memory: Der langlebige persönliche Kontext <a class="header-anchor" href="#hermes-memory-der-langlebige-personliche-kontext" aria-label="Permalink to &quot;Hermes-Memory: Der langlebige persönliche Kontext&quot;">​</a></h2><p>Hermes verfolgt beim Thema Gedächtnis einen anderen Ansatz. Statt einer einzigen Memory-Datei nutzt Hermes ein mehrstufiges Gedächtnissystem mit verschiedenen Ebenen.</p><p>Das kurzfristige Gedächtnis ist der aktuelle Sitzungskontext: Was wurde besprochen, welche Aufgaben wurden durchgeführt, welche Entscheidungen getroffen. Dieses Gedächtnis gilt nur für die laufende Sitzung.</p><p>Das langfristige Gedächtnis ist in MEMORY.md und USER.md gespeichert. MEMORY.md enthält Fakten über laufende Projekte, bevorzugte Arbeitsweisen und wiederkehrende Aufgaben. USER.md ist ein wachsendes Profil Ihrer Persönlichkeit, Kommunikationspräferenzen und Arbeitsstile. Hermes nutzt außerdem ein sogenanntes dialektisches Nutzermodell, das über Sitzungen hinweg ein immer genaueres Bild Ihrer Arbeitsweise entwickelt.</p><p>Das dritte Gedächtnissystem sind Skills. Sie werden im nächsten Abschnitt ausführlicher behandelt.</p><p>Was Hermes besonders macht, ist die Fähigkeit zur Volltextsuche über vergangene Sitzungen mit anschließender KI-Zusammenfassung. Sie können also nicht nur sagen &quot;Was haben wir letzten Monat über Projekt X besprochen?&quot;, sondern Hermes durchsucht seine eigene Sitzungsgeschichte und liefert eine kohärente Zusammenfassung. Das ist ein erheblicher Vorteil gegenüber Agenten, die jede Sitzung von null beginnen.</p><h2 id="skills-wiederverwendbare-fahigkeitsmuster" tabindex="-1">Skills: Wiederverwendbare Fähigkeitsmuster <a class="header-anchor" href="#skills-wiederverwendbare-fahigkeitsmuster" aria-label="Permalink to &quot;Skills: Wiederverwendbare Fähigkeitsmuster&quot;">​</a></h2><p>Skills sind ein Konzept, das sich in allen vier Agenten-Werkzeugen findet und das für Selbständige besonders wertvoll ist.</p><p>Ein Skill ist eine gespeicherte Arbeitsanweisung für eine bestimmte Art von Aufgabe. Statt bei jedem Recherche-Auftrag erneut zu schreiben, wie das Ergebnis strukturiert sein soll, speicherst Sie dieses Wissen als Skill. Der Agent ruft den Skill ab, wenn er gebraucht wird, und arbeitet danach, ohne dass Sie die Anweisung jedes Mal wiederholen musst.</p><p>Bei Claude Code werden Skills als eigene Dateien im Projektordner gespeichert und sind sofort verfügbar, sobald sie gespeichert werden, ohne dass die Sitzung neu gestartet werden muss. Die empfohlene Vorgehensweise beim Aufbau von Skills ist iterativ: Einen Skill für den eigenen Gebrauch entwickeln, im Projekt testen, nach zwei bis drei Iterationen verfeinern und dann als feste Ressource einbinden.</p><p>Bei Hermes gehen Skills noch einen Schritt weiter. Wenn Hermes eine komplexe Aufgabe erfolgreich abgeschlossen hat, zum Beispiel die Strukturierung einer Wettbewerbsanalyse, kann er aus dieser Erfahrung selbständig einen Skill erstellen: eine gespeicherte Beschreibung der Schritte, Methoden und Entscheidungen, die zum Erfolg geführt haben. Beim nächsten ähnlichen Auftrag ruft Hermes diesen Skill ab und startet nicht von null. Skills in Hermes folgen dem offenen Standard von agentskills.io und sind damit portierbar und teilbar.</p><p>Für Selbständige sind besonders folgende Skills am Anfang nützlich. Ein Recherche-Skill enthält eine Anweisung, wie Recherchen strukturiert sein sollen: Kurzfazit, Fakten mit Quellen, Unsicherheiten markiert, Format definiert. Ein Meeting-Nachbereitungs-Skill enthält eine Anweisung, wie aus einer Mitschrift Aufgaben, Entscheidungen und Follow-up-Entwürfe extrahiert werden. Ein Text-Review-Skill enthält Anweisungen für Stilkorrekturen: Was soll geprüft werden, nach welchem Stilprofil, in welchem Ausgabeformat. Ein Backoffice-Skill enthält eine Anweisung, wie Belege und Dokumente geordnet und benannt werden sollen.</p><h2 id="hooks-regeln-die-immer-gelten" tabindex="-1">Hooks: Regeln, die immer gelten <a class="header-anchor" href="#hooks-regeln-die-immer-gelten" aria-label="Permalink to &quot;Hooks: Regeln, die immer gelten&quot;">​</a></h2><p>Hooks sind automatische Aktionen, die bei bestimmten Ereignissen ausgelöst werden. Sie funktionieren unabhängig davon, was der Agent im Moment plant. Während eine CLAUDE.md-Anweisung den Agenten lenkt, aber nicht erzwingt, setzt ein Hook eine Regel deterministisch durch.</p><p>Claude Code unterstützt verschiedene Hook-Typen. Ein PreToolUse-Hook wird ausgelöst, bevor ein Werkzeug aufgerufen wird, und kann die Aktion prüfen oder blockieren. Ein Stop-Hook wird ausgelöst, wenn Claude Code eine Antwort fertiggestellt hat, und kann die Ausgabe noch einmal prüfen. Ein UserPromptSubmit-Hook wird ausgelöst, bevor Ihr Prompt das Modell erreicht, und kann zusätzliche Anweisungen hinzufügen.</p><p>Für Selbständige sind Hooks am nützlichsten als Sicherheitsnetz: Ein Hook, der jede E-Mail-Sendeanfrage automatisch blockiert und zur menschlichen Bestätigung weiterleitet. Ein Hook, der nach jeder Sitzung automatisch eine Zusammenfassung in eine Protokolldatei schreibt. Ein Hook, der vor jeder Dateiänderung den Dateinamen und den geplanten Inhalt der Änderung protokolliert.</p><p>Die Empfehlung aus der Praxis lautet: Hooks sollten am Ende der Arbeit laufen, nicht während jedes einzelnen Schritts. Zu viele Unterbrechungen während der Arbeit machen die Arbeit mit dem Agenten mühsam. Ein finaler Prüf-Hook, der nach Abschluss einer Aufgabe das Gesamtergebnis bewertet, ist produktiver als ein Hook, der nach jedem Einzelschritt unterbricht.</p><h2 id="routinen-wiederkehrende-aufgaben-automatisch-anstoßen" tabindex="-1">Routinen: Wiederkehrende Aufgaben automatisch anstoßen <a class="header-anchor" href="#routinen-wiederkehrende-aufgaben-automatisch-anstoßen" aria-label="Permalink to &quot;Routinen: Wiederkehrende Aufgaben automatisch anstoßen&quot;">​</a></h2><p>Der letzte Baustein des persönlichen Agenten-Systems sind Routinen, also zeitgesteuerte oder situationsgesteuerte Abläufe, die regelmäßig ausgeführt werden.</p><p>Hermes hat dafür ein integriertes Cron-System, das Aufgaben zu bestimmten Zeiten oder nach bestimmten Ereignissen automatisch startet. Ein Hermes-Agent kann zum Beispiel jeden Montag um acht Uhr morgens automatisch die Wochenplanung anstoßen: Kalenderereignisse der Woche prüfen, offene Aufgaben aus der letzten Woche zusammenfassen, Prioritäten für heute vorschlagen.</p><p>Claude Code und Codex unterstützen Routinen über Automations-Konfigurationen, die in den jeweiligen Einstellungsdateien definiert werden. In Codex werden wiederkehrende Aufgaben als Automations beschrieben und können als regelmäßige Prozesse eingerichtet werden.</p><p>Besonders nützliche Routinen für Selbständige sind:</p><p>Das tägliche Morgenbriefing: Kalender des Tages, drei wichtigste offene Aufgaben, dringende E-Mails, Fristen der nächsten 48 Stunden. Dieser Routine dauert für den Agenten zwei bis drei Minuten, spart Ihnen aber die Zeit, alle diese Informationen selbst zusammenzusuchen.</p><p>Die wöchentliche Rückschau: Was wurde abgeschlossen? Was ist offen geblieben? Was wurde gelernt? Was muss die nächste Woche passieren?</p><p>Der Freitagsabschluss: Belege der Woche prüfen, Dateinamen vereinheitlichen, offene Rechnungen markieren, Aufgabenliste für die nächste Woche vorbereiten.</p><p>Das monatliche Reporting: Einnahmen, Ausgaben, abgeschlossene Projekte, offene Posten, drei wichtigste Erkenntnisse des Monats.</p><p>Jede dieser Routinen muss einmalig konfiguriert werden. Danach läuft sie automatisch, und Sie bekommen ein strukturiertes Briefing, das Sie prüfen, korrigierst und als Entscheidungsgrundlage nutzt.</p><h2 id="der-schrittweise-aufbau-eine-empfehlung-fur-die-praxis" tabindex="-1">Der schrittweise Aufbau: Eine Empfehlung für die Praxis <a class="header-anchor" href="#der-schrittweise-aufbau-eine-empfehlung-fur-die-praxis" aria-label="Permalink to &quot;Der schrittweise Aufbau: Eine Empfehlung für die Praxis&quot;">​</a></h2><p>Der häufigste Fehler beim Aufbau eines persönlichen Agenten-Systems ist der Versuch, alles auf einmal einzurichten. Das Ergebnis ist ein System, das zu komplex ist, das Sie nicht wirklich verstehst und das beim ersten Problem zusammenbricht.</p><p>Die bessere Strategie ist schrittweise. In der ersten Woche legst Sie eine einfache CLAUDE.md oder AGENTS.md an mit den wichtigsten Informationen über Sie und Ihre Arbeit. Dann nimmst Sie eine Aufgabe, die Sie regelmäßig erledigst, und richtest dafür einen ersten Skill ein. Sie nutzen diesen Skill eine Woche lang täglich und prüfst dabei: Folgt der Agent der Anweisung? Fehlt ihm Kontext? Was muss verbessert werden?</p><p>In der zweiten Woche fügst Sie eine erste Routine hinzu. Das Morgenbriefing ist ein guter Einstieg, weil es täglich läuft, schnell zu konfigurieren ist und sofortige Rückmeldung darüber gibt, ob der Kontext stimmt.</p><p>In der dritten Woche richtest Sie einen oder zwei Hooks ein, die als Sicherheitsnetz dienen. Ein einfacher Hook, der nach jeder Sitzung eine kurze Protokollnotiz schreibt, ist ein guter Anfang.</p><p>Ab der vierten Woche können Sie das System schrittweise erweitern: neue Skills für neue Aufgabentypen, neue Routinen für wiederkehrende Abläufe, neue Kontextinformationen für neue Projekte.</p><p>Das System muss nicht fertig sein. Es muss nützlich sein. Und es wird mit jeder Woche nützlicher, wenn Sie es konsequent pflegst und weiterentwickelst.</p><h2 id="ein-konkretes-beispiel-das-projektordner-setup" tabindex="-1">Ein konkretes Beispiel: Das Projektordner-Setup <a class="header-anchor" href="#ein-konkretes-beispiel-das-projektordner-setup" aria-label="Permalink to &quot;Ein konkretes Beispiel: Das Projektordner-Setup&quot;">​</a></h2><p>Stellen Sie sich vor, Sie betreuen drei verschiedene Kundenprojekte gleichzeitig. Für jedes Projekt gibt es einen eigenen Ordner auf Ihrem Computer. In jedem Ordner liegt eine CLAUDE.md oder AGENTS.md, die folgendes enthält: eine kurze Beschreibung des Projekts und des Kunden, den aktuellen Stand, die wichtigsten nächsten Schritte, die wichtigsten Stilregeln für diesen Kunden sowie Dinge, die bei diesem Projekt besonders beachtet werden müssen.</p><p>Wenn Sie Claude Code in einem dieser Ordner startest, liest der Agent zuerst die globale CLAUDE.md mit allgemeinen Informationen über Sie, dann die projektspezifische Datei mit dem Projektkontext. Ohne einen einzigen Satz erklären zu müssen, ist der Agent im richtigen Kontext für die Arbeit an diesem Projekt.</p><p>Das ist das Kernversprechen eines gut aufgebauten persönlichen Agenten-Systems: Nicht mehr Zeit damit zu verbringen, dem Agenten zu erklären, wer Sie sind und was Sie brauchen, sondern sofort mit der eigentlichen Aufgabe beginnen zu können.</p>',67)),d(n)])}const p=i(l,[["render",o]]);export{f as __pageData,p as default};
